package org.apache.commons.collections4.iterators;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.ListIterator;
import java.util.NoSuchElementException;

import org.apache.commons.collections4.ResettableListIterator;
import org.junit.jupiter.api.Test;

/**
 * Tests the ReverseListIterator.
 */
public class ReverseListIteratorTest<E> extends AbstractListIteratorTest<E> {

    protected String[] testArray = { "One", "Two", "Three", "Four" };

    public ReverseListIteratorTest() {
        super(ReverseListIteratorTest.class.getSimpleName());
    }

    @Override
    public ListIterator<E> makeEmptyIterator() {
        return new ReverseListIterator<>(new ArrayList<>());
    }

    @Override
    @SuppressWarnings("unchecked")
    public ReverseListIterator<E> makeObject() {
        final List<E> list = new ArrayList<>(Arrays.asList((E[]) testArray));
        return new ReverseListIterator<>(list);
    }

    // overrides
    @Test
    @Override
    public void testEmptyListIteratorIsIndeedEmpty() {
        final ListIterator<E> it = makeEmptyIterator();

        assertFalse(it.hasNext());
        assertEquals(-1, it.nextIndex());  // reversed index
        assertFalse(it.hasPrevious());
        assertEquals(0, it.previousIndex());  // reversed index

        assertAll(
                // next() should throw a NoSuchElementException
                () -> assertThrows(NoSuchElementException.class, () -> it.next(),
                        "NoSuchElementException must be thrown from empty ListIterator"),
                // previous() should throw a NoSuchElementException
                () -> assertThrows(NoSuchElementException.class, () -> it.previous(),
                        "NoSuchElementException must be thrown from empty ListIterator")
        );
    }

    @Test
    @Override
    public void testWalkForwardAndBack() {
        final ArrayList<E> list = new ArrayList<>();
        final ListIterator<E> it = makeObject();
        while (it.hasNext()) {
            list.add(it.next());
        }

        // check state at end
        assertFalse(it.hasNext());
        assertTrue(it.hasPrevious());

        // this had to be commented out, as there is a bug in the JDK before JDK1.5
        // where calling previous at the start of an iterator would push the cursor
        // back to an invalid negative value
//        try {
//            it.next();
//            fail("NoSuchElementException must be thrown from next at end of ListIterator");
//        } catch (NoSuchElementException e) {
//        }

        // loop back through comparing
        for (int i = list.size() - 1; i >= 0; i--) {
            assertEquals(list.size() - i - 2, it.nextIndex(), "" + i);  // reversed index
            assertEquals(list.size() - i - 1, it.previousIndex());  // reversed index

            final Object obj = list.get(i);
            assertEquals(obj, it.previous());
        }

        // check state at start
        assertTrue(it.hasNext());
        assertFalse(it.hasPrevious());

        assertThrows(NoSuchElementException.class, () -> it.previous(),
                "NoSuchElementException must be thrown from previous at start of ListIterator");
    }

    @Test
    public void testReverse() {
        final ListIterator<E> it = makeObject();
        assertTrue(it.hasNext());
        assertEquals(3, it.nextIndex());
        assertFalse(it.hasPrevious());
        assertEquals(4, it.previousIndex());
        assertEquals("Four", it.next());
        assertEquals(2, it.nextIndex());
        assertTrue(it.hasNext());
        assertEquals(3, it.previousIndex());
        assertTrue(it.hasPrevious());
        assertEquals("Three", it.next());
        assertTrue(it.hasNext());
        assertEquals(1, it.nextIndex());
        assertTrue(it.hasPrevious());
        assertEquals(2, it.previousIndex());
        assertEquals("Two", it.next());
        assertTrue(it.hasNext());
        assertEquals(0, it.nextIndex());
        assertTrue(it.hasPrevious());
        assertEquals(1, it.previousIndex());
        assertEquals("One", it.next());
        assertFalse(it.hasNext());
        assertEquals(-1, it.nextIndex());
        assertTrue(it.hasPrevious());
        assertEquals(0, it.previousIndex());
        assertEquals("One", it.previous());
        assertEquals("Two", it.previous());
        assertEquals("Three", it.previous());
        assertEquals("Four", it.previous());
    }

    @Test
    public void testReset() {
        final ResettableListIterator<E> it = makeObject();
        assertEquals("Four", it.next());
        it.reset();
        assertEquals("Four", it.next());
        it.next();
        it.next();
        it.reset();
        assertEquals("Four", it.next());
    }

}

package edu.isi.vista.gigawordIndexer;

import com.google.common.collect.AbstractIterator;

import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;
import java.io.InputStream;
import java.io.FileInputStream;
import java.nio.file.Path;
import java.util.Iterator;
import java.util.List;
import java.util.zip.GZIPInputStream;

/**
 * The LDC distributes annotated Gigaword as a moderate number of gzipped files, each of which has many documents
 * concatenated together. This class lets you iterate over the documents stored in such a file. This class was
 * authored by the UKP Lab of Technische Universität Darmstadt and is included here for their convenience.
 */

public class ConcatenatedAnnotatedGigawordDocuments implements ArticleSource {
    private List<Article> articleList;

    private ConcatenatedAnnotatedGigawordDocuments(List<Article> aArticleList) {
        this.articleList = aArticleList;
    }

    public static ConcatenatedAnnotatedGigawordDocuments fromAnnotatedGigwordGZippedFile(Path p) throws Exception {
        // Initialize Streams
        try (InputStream fileInputStream = new FileInputStream(p.toString());
             GZIPInputStream gzipInputStream = new GZIPInputStream(fileInputStream)) {

            SAXParserFactory factory = SAXParserFactory.newInstance();
            SAXParser saxParser = factory.newSAXParser();
            AnnotatedGigawordParser parser = new AnnotatedGigawordParser();
            saxParser.parse(gzipInputStream, parser);

            return new ConcatenatedAnnotatedGigawordDocuments(parser.getArticleList());
        }
    }

    public Iterator<Article> iterator() {
        return new AnnotatedArticlesIterator();
    }

    @Override
    public void close() throws Exception
    {

    }

    private class AnnotatedArticlesIterator extends AbstractIterator<Article> {

        private int startNextIndex = 0;

        @Override
        protected Article computeNext() {

            if (startNextIndex >= articleList.size()) {
                return endOfData();
            }

            else
            {
                Article nextArticle = articleList.get(startNextIndex);
                startNextIndex ++;
                return nextArticle;
            }
        }
    }
}

