from __future__ import print_function
from flask import Flask, request, redirect, jsonify
import xmltodict
import json
from typing import Dict, List, Union
from peewee import SqliteDatabase, Model, CharField, DateTimeField
from datetime import datetime

# Mock implementation of the cdrs module and models.Record class
class CDRTypeA:
    def __init__(self, data: Dict):
        self.type = 'A'
        self.data = data

class CDRTypeB:
    def __init__(self, data: Dict):
        self.type = 'B'
        self.data = data

cdrs = {
    'A': CDRTypeA,
    'B': CDRTypeB
}

# Mock implementation of the Record model using Peewee ORM
db = SqliteDatabase(':memory:')

class Record(Model):
    data = CharField()
    created_date = DateTimeField(default=datetime.now)

    class Meta:
        database = db

    @classmethod
    def create(cls, **query):
        instance = cls(**query)
        instance.save()
        return instance

    @property
    def serialize(self) -> str:
        return self.data

db.connect()
db.create_tables([Record])

app = Flask(__name__)

@app.route('/')
def index():
    """Redirects the root URL to the admin page."""
    return redirect('/admin/')

@app.route('/cdr', methods=['POST'])
def post_call_detail_record():
    """
    Handles POST requests to /cdr endpoint.
    Parses XML data, creates Record instances, and stores them in the database.
    """
    try:
        parsed_cdr_data = parse_call_detail_record(request.data)
        save_records(parsed_cdr_data)
        return '', 204
    except Exception as error:
        print(f'Parser failure: {str(error)}')
        return '', 500

def parse_call_detail_record(data: bytes) -> Dict:
    """
    Parses XML data into a dictionary.

    Args:
        data (bytes): Raw XML data from the request.

    Returns:
        Dict: Parsed dictionary representation of the XML data.
    """
    return xmltodict.parse(data)

def save_records(parsed_cdr_data: Dict):
    """
    Creates Record instances from parsed CDR data and stores them in the database.

    Args:
        parsed_cdr_data (Dict): Parsed dictionary representation of the CDR data.
    """
    records = parsed_cdr_data.get('records', {}).get('record', [])
    if not isinstance(records, list):
        records = [records]

    for record in records:
        record_type = record.get('@type')
        if record_type in cdrs:
            record_instance = cdrs[record_type](record)
            Record.create(data=json.dumps(record_instance.__dict__))

@app.route('/api/v1/records/', methods=['GET'])
@app.route('/api/v1/records/<int:page>', methods=['GET'])
def get_records(page: int = 1) -> jsonify:
    """
    Handles GET requests to /api/v1/records/ endpoint.
    Retrieves paginated records from the database and returns them as JSON.

    Args:
        page (int): Page number for pagination (default is 1).

    Returns:
        jsonify: JSON response containing the records.
    """
    per_page = 20
    query = Record.select().paginate(page, per_page).order_by(Record.created_date.desc())
    records = [json.loads(record.serialize) for record in query]

    return jsonify({'records': records}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8444)
